import type { WorkState } from '@turbine-hall/turbine-contracts';
import type { RepoFacts } from '../changeset.js';
import type { FlowStep } from './normalize.js';

/**
 * Mermaid diagrams generated by the engine from data — never drawn by a model.
 * Renders on GitHub; in Cursor/VS Code install "Markdown Preview Mermaid Support".
 */
const label = (t: string) => `"${t.replace(/"/g, "'").replace(/[\n\r]+/g, ' ').slice(0, 60)}"`;

const STAGES: Array<{ id: string; name: string; states: WorkState[] }> = [
  { id: 'req', name: 'Request', states: ['IMPORTED', 'ASSESSING'] },
  { id: 'spec', name: 'Requirements', states: ['NEEDS_CLARIFICATION', 'REQUIREMENTS_REVIEW'] },
  { id: 'plan', name: 'Plan', states: ['REQUIREMENTS_APPROVED', 'PLANNING', 'PLAN_REVIEW'] },
  { id: 'code', name: 'Code', states: ['PLAN_APPROVED', 'IMPLEMENTING', 'CHANGES_REQUESTED'] },
  { id: 'review', name: 'Code review', states: ['AI_REVIEW', 'HUMAN_CODE_REVIEW'] },
  { id: 'checks', name: 'Checks', states: ['VERIFYING'] },
  { id: 'accept', name: 'Acceptance', states: ['HUMAN_ACCEPTANCE'] },
];

/** Gate progress: done ✓, current ●, upcoming ○. */
export function gateFlow(state: WorkState): string {
  const idx = state === 'ACCEPTED' ? STAGES.length : STAGES.findIndex((s) => s.states.includes(state));
  const nodes = STAGES.map((s, i) => {
    const mark = i < idx ? '✓' : i === idx ? '●' : '○';
    return `  ${s.id}[${label(`${mark} ${s.name}`)}]`;
  });
  const edges = STAGES.slice(1).map((s, i) => `  ${STAGES[i]!.id} --> ${s.id}`);
  const classes = STAGES.map((s, i) => `  class ${s.id} ${i < idx ? 'done' : i === idx ? 'now' : 'todo'}`);
  return [
    '```mermaid',
    'flowchart LR',
    ...nodes,
    ...edges,
    '  classDef done fill:#d3f9d8,stroke:#2b8a3e,color:#1b4332',
    '  classDef now fill:#fff3bf,stroke:#e67700,color:#5c3c00,stroke-width:2px',
    '  classDef todo fill:#f1f3f5,stroke:#adb5bd,color:#495057',
    ...classes,
    '```',
  ].join('\n');
}

/** Change map (repo → folder → file). Only worth drawing when the change spans folders or repos. */
export function changeMap(facts: RepoFacts[], maxFiles = 14): string | undefined {
  const files = facts.flatMap((f) => f.files.map((x) => ({ repo: f.repo, path: x.path, status: x.status })));
  const folders = new Set(files.map((f) => `${f.repo}/${f.path.split('/')[0]}`));
  if (files.length < 2 || (facts.length < 2 && folders.size < 2)) return undefined;
  const lines = ['```mermaid', 'flowchart LR'];
  const seen = new Set<string>();
  let n = 0;
  for (const f of files.slice(0, maxFiles)) {
    const r = `r_${f.repo.replace(/[^a-z0-9]/gi, '_')}`;
    const dir = f.path.includes('/') ? f.path.split('/').slice(0, -1).join('/') : '.';
    const d = `${r}_d_${dir.replace(/[^a-z0-9]/gi, '_')}`;
    if (!seen.has(r)) {
      lines.push(`  ${r}[${label(`📦 ${f.repo}`)}]`);
      seen.add(r);
    }
    if (!seen.has(d)) {
      lines.push(`  ${d}[${label(`📁 ${dir}`)}]`, `  ${r} --> ${d}`);
      seen.add(d);
    }
    const id = `f${n++}`;
    const tag = f.status === 'A' ? '+ ' : f.status === 'D' ? '− ' : '~ ';
    lines.push(`  ${id}[${label(`${tag}${f.path.split('/').pop()}`)}]`, `  ${d} --> ${id}`);
  }
  if (files.length > maxFiles) lines.push(`  more[${label(`… ${files.length - maxFiles} more files`)}]`);
  lines.push('```');
  return lines.join('\n');
}

/** User flow as a sequence diagram (from structured spec data). */
export function userFlowDiagram(steps: FlowStep[]): string | undefined {
  if (steps.length < 2) return undefined;
  const actors = [...new Set(steps.flatMap((s) => [s.from, s.to]))];
  const id = (a: string) => `a${actors.indexOf(a)}`;
  // Escape Mermaid-significant punctuation (decimal entities) so balance lint stays green
  // without destroying route/shape meaning such as `GET /users/{id}` or `[]`.
  const clean = (s: string, max: number) => {
    const hash = '\uE000';
    const semi = '\uE001';
    const ent = (n: number) => `${hash}${n}${semi}`;
    return s
      .replace(/#/g, ent(35))
      .replace(/;/g, ent(59))
      .replace(/"/g, ent(34))
      .replace(/`/g, ent(96))
      .replace(/\(/g, ent(40))
      .replace(/\)/g, ent(41))
      .replace(/\[/g, ent(91))
      .replace(/\]/g, ent(93))
      .replace(/\{/g, ent(123))
      .replace(/\}/g, ent(125))
      .replace(new RegExp(hash, 'g'), '#')
      .replace(new RegExp(semi, 'g'), ';')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, max);
  };
  return [
    '```mermaid',
    'sequenceDiagram',
    ...actors.map((a) => `  participant ${id(a)} as ${clean(a, 30)}`),
    ...steps.slice(0, 15).map((s) => `  ${id(s.from)}->>${id(s.to)}: ${clean(s.message, 70)}`),
    '```',
  ].join('\n');
}
